structure.mermaidSource:
flowchart TD
  start["Início: Análise da Lacuna"] --> dec_det{"Há determinante antes da lacuna?<br/>(artigo, pronome, numeral, contração)"}
  dec_det -- "Sim" --> res_porque_subst["PORQUÊ (junto e com acento)<br/>Classe: Substantivo ('o motivo')"]
  dec_det -- "Não" --> dec_causa{"Introduz justificativa, causa ou finalidade?<br/>(comutável por 'pois' ou 'para que')"}
  dec_causa -- "Sim" --> res_porque_conj["PORQUE (junto e sem acento)<br/>Classe: Conjunção (causal/explicativa)"]
  dec_causa -- "Não" --> dec_pausa{"Está imediatamente antes de pausa/pontuação?<br/>(?, ., !, ...)"}
  dec_pausa -- "Sim" --> res_por_que_tonico["POR QUÊ (separado e com acento)<br/>Classe: Interrogativo tônico em fim de oração"]
  dec_pausa -- "Não" --> res_por_que_atono["POR QUE (separado e sem acento)<br/>Classe: Prep. por + pronome/conjunção"]

flowchart TD
  start["Início: Análise de Período com Conjectura"] --> dec_verbo_conjectura{"Há verbo de dúvida, cognição ou questionamento?"}
  dec_verbo_conjectura -- "Sim" --> proc_teste_motivo["Teste de inserção da palavra 'motivo' após 'que'"]
  dec_verbo_conjectura -- "Não" --> res_descartar["Descartar interrogativa indireta por conjectura\nAvaliar outros valores dos porquês"]
  proc_teste_motivo --> dec_cabe_motivo{"O encaixe de 'motivo' mantém o sentido exato?"}
  dec_cabe_motivo -- "Sim" --> proc_teste_direta["Teste da Pergunta Direta: isolar a oração com '? '"]
  dec_cabe_motivo -- "Não" --> res_rejeitar_motivo["Hipótese interrogativa rejeitada\nTestar conjunção explicativa/causal"]
  proc_teste_direta --> dec_valida_direta{"A oração isolada forma pergunta direta coerente?"}
  dec_valida_direta -- "Sim" --> dec_posicao{"Qual a posição sintática na oração?"}
  dec_valida_direta -- "Não" --> res_reavaliar_sintaxe["Não confirmada como interrogativa direta"]
  dec_posicao -- "Início ou meio" --> res_por_que["Grafar 'por que'\nSeparado e sem acento\nEx: Não sabia por que os aparelhos..."]
  dec_posicao -- "Final ou antes de pausa" --> res_por_que_acento["Grafar 'por quê'\nSeparado e com acento circunflexo\nEx: Foram questionados por quê."]
